import { AsyncLocalStorage } from 'node:async_hooks';

export interface RequestContext { requestId: string; tenantId: string }
export const requestContext = new AsyncLocalStorage<RequestContext>();

// boundary: bind the typed store for the whole request
requestContext.run({ requestId: randomUUID(), tenantId }, () => app.handle(req));

export function currentContext(): RequestContext {
  const ctx = requestContext.getStore();
  if (!ctx) throw new Error('request context missing');
  return ctx;                                    // typed, non-optional
}
